<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LZDS Computer Laboratory Logbook</title>@vite('resources/css/app.css')</head><body><header class="top"><div class="brand"><img class="brand-logo" src="{{ asset('/images/LZDS-LOGO.png') }}" alt="LZDS logo"><span>COMPUTER LABORATORY</span></div><a href="{{ route('admin.login') }}">Administrator</a></header><main class="wrap"><section class="hero"><div class="eyebrow">LORD OF ZION DIVINE SCHOOL</div><h1>Computer Laboratory Logbook</h1><p>Welcome. Please record your computer use and remember to check out when you finish.</p><div class="unit">Assigned Computer: <strong>{{ $computer?->pc_number ?? 'Not registered' }}</strong></div></section>
