@if(!$computer)<section class="card"><h2>This computer is not registered</h2><p>Please tell the laboratory administrator. Do not use another computer’s assigned number.</p></section>@elseif($active)<section class="card active"><div class="eyebrow">ACTIVE SESSION</div><h2>Hello, {{ $active->first_name }} {{ $active->last_name }}</h2><p>Checked in at {{ $active->time_in->format('g:i A') }} on {{ $active->time_in->format('M j, Y') }}.</p><form method="post" action="{{ route('checkout') }}">@csrf<button class="button red" type="submit">Check out now</button></form></section>@else<section class="card"><h2>Student check-in</h2><form method="post" action="{{ route('checkin') }}">@csrf<div class="grid"><label>First Name<input name="first_name" value="{{ old('first_name') }}" required maxlength="80" autocomplete="given-name"></label><label>Last Name<input name="last_name" value="{{ old('last_name') }}" required maxlength="80" autocomplete="family-name"></label><label>Student ID <span class="muted">(Optional)</span><input name="student_id" value="{{ old('student_id') }}" maxlength="60"></label><label>Grade Level<select name="grade_level_id" required><option value="">Choose grade level</option>@foreach($grades as $g)<option value="{{ $g->id }}" @selected(old('grade_level_id')==$g->id)>{{ $g->name }}</option>@endforeach</select></label><label>Subject<select name="subject_id" required><option value="">Choose subject</option>@foreach($subjects as $s)<option value="{{ $s->id }}" @selected(old('subject_id')==$s->id)>{{ $s->name }}</option>@endforeach</select></label><label>Reason for computer use<select name="usage_reason_id" id="reason" required><option value="">Choose a reason</option>@foreach($reasons as $r)<option value="{{ $r->id }}" data-other="{{ strtolower($r->name)==='other'?'1':'0' }}">{{ $r->name }}</option>@endforeach</select></label><label class="wide hidden" id="other-wrap">Please describe<input name="other_reason_details" maxlength="255"></label></div><button class="button" type="submit">Check in</button></form></section>@endif<footer>Time is recorded automatically by the school server.</footer></main><script>const reason=document.querySelector('#reason');reason?.addEventListener('change',()=>document.querySelector('#other-wrap').classList.toggle('hidden',reason.selectedOptions[0]?.dataset.other!=='1'));</script></body></html>
